function_name='UART_EndRxTransfer' replacement_code='static void UART_EndRxTransfer(UART_HandleTypeDef *huart)
{
  /* Skip hardware-specific atomic operations for interrupt disable */
  /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR1, (USART_CR1_RXNEIE | USART_CR1_PEIE)); */
  /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR3, USART_CR3_EIE); */

  /* In case of reception waiting for IDLE event, disable also the IDLE IE interrupt source */
  if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
  {
    /* Skip hardware-specific atomic operation */
    /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR1, USART_CR1_IDLEIE); */
  }

  /* At end of Rx process, restore huart->RxState to Ready */
  huart->RxState = HAL_UART_STATE_READY;
  huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;
}' reason='Fixed exceptional loop issue in UART_EndRxTransfer. The function contains ATOMIC_CLEAR_BIT operations that use ARM-specific atomic instructions (__LDREXW/__STREXW) which were causing issues in emulation. These operations have been removed while preserving the state management functionality. The function now properly updates the UART handle state without accessing hardware registers, allowing the emulation to proceed without getting stuck on hardware-specific atomic operations.'

function_name='HAL_UART_IRQHandler' replacement_code="void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Simplified interrupt handler for emulation */
  /* Skip all hardware register reads and complex interrupt flag checking */

  /* In emulation, we simulate the most common interrupt scenarios */

  /* Check if we're in receive mode */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate data received - read from stdin */
    if (huart->pRxBuffPtr != NULL && huart->RxXferSize > 0)
    {
      /* Read available data */
      int bytes_read = HAL_BE_In(huart->pRxBuffPtr, huart->RxXferSize);
      if (bytes_read > 0)
      {
        huart->RxXferCount = huart->RxXferSize - bytes_read;

        /* Call receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->RxCpltCallback != NULL)
        {
          huart->RxCpltCallback(huart);
        }
#else
        HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Check if we're in transmit mode */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Simulate transmission complete */
    huart->gState = HAL_UART_STATE_READY;

    /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->TxCpltCallback != NULL)
    {
      huart->TxCpltCallback(huart);
    }
#else
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    return;
  }

  /* Handle error cases */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->ErrorCallback != NULL)
    {
      huart->ErrorCallback(huart);
    }
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    huart->ErrorCode = HAL_UART_ERROR_NONE;
